import{_ as o,o as d,c,a4 as t}from"./chunks/framework.BBs01uty.js";const p=JSON.parse('{"title":"机制六：后台任务（TaskManager / 面板 / 详情）","description":"","frontmatter":{},"headers":[],"relativePath":"agent-cli/mechanisms/background-tasks.md","filePath":"agent-cli/mechanisms/background-tasks.md"}'),s={name:"agent-cli/mechanisms/background-tasks.md"};function a(n,e,l,i,r,u){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="机制六-后台任务-taskmanager-面板-详情" tabindex="-1">机制六：后台任务（TaskManager / 面板 / 详情） <a class="header-anchor" href="#机制六-后台任务-taskmanager-面板-详情" aria-label="Permalink to &quot;机制六：后台任务（TaskManager / 面板 / 详情）&quot;">​</a></h1><blockquote><p>对应 <code>src/tasks.ts</code>（715 行）、<code>src/ui/task-panel.ts</code>、<code>src/ui/fullscreen.ts</code>， 以及 <code>index.ts</code> 的 <code>runBangCommand</code>（<code>!</code> 模式）与工具层 <code>bash(run_in_background)</code>。</p></blockquote><h2 id="_1-职责边界" tabindex="-1">1. 职责边界 <a class="header-anchor" href="#_1-职责边界" aria-label="Permalink to &quot;1. 职责边界&quot;">​</a></h2><ul><li><code>tasks.ts</code> 只管：<strong>spawn / 进程组 / 输出采集 / 生命周期</strong>。不碰终端。</li><li><strong>面板与详情是 <code>ui/</code> 的纯逻辑</strong>，通过结构化端口 <code>TaskPanelSource</code>（<code>list</code> / <code>tailOutput</code> / <code>kill</code> / 可选 <code>refreshJobStates</code> / <code>forget</code> / <code>forgetFinished</code>）读数据 —— 便于 e2e 注入真实子进程或替身。</li><li>数据源在 <code>index.ts</code> <strong>唯一接线</strong>：<code>ui.setTaskPanelSource(tasks)</code>（<code>TaskManager</code> 结构上满足该端口）。</li></ul><h2 id="_2-任务生命周期" tabindex="-1">2. 任务生命周期 <a class="header-anchor" href="#_2-任务生命周期" aria-label="Permalink to &quot;2. 任务生命周期&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>start(command, {background})</span></span>\n<span class="line"><span>  spawn(&#39;sh&#39;, [&#39;-c&#39;, command], { detached: true, stdio:[&#39;ignore&#39;,&#39;pipe&#39;,&#39;pipe&#39;] })</span></span>\n<span class="line"><span>  → state = &#39;running&#39;（pgid = pid，整组可回收）</span></span>\n<span class="line"><span>     │</span></span>\n<span class="line"><span>     ├─ child.on(&#39;exit&#39;) 且进程组已空 ──────→ &#39;exited&#39;</span></span>\n<span class="line"><span>     ├─ child.on(&#39;exit&#39;) 但进程组仍有成员 ──→ 保持 &#39;running&#39;（shellExited = true）</span></span>\n<span class="line"><span>     │        ↑ F2：`cmd &amp;` / nohup 派生的后台进程还在跑，不能标&quot;已结束&quot;</span></span>\n<span class="line"><span>     │          由 refreshJobStates() 在进程组清空后收尾为 &#39;exited&#39;</span></span>\n<span class="line"><span>     └─ kill(id) ─────────────────────────→ &#39;killed&#39;（幂等：再 kill 返回 alreadyExited）</span></span></code></pre></div><p>要点：</p><ul><li><strong>spawn 即返回</strong>（<code>{taskId, pid, running:true}</code>），不 await 进程结束。</li><li>task id 形如 <code>task-&lt;base36 时间&gt;-&lt;base36 序号&gt;</code>，过白名单 <code>TASK_ID_PATTERN</code>（<code>/^[a-z0-9-]+$/</code>）—— <strong>按 id 拼路径在结构上不可能</strong>（先查表，未命中即 null）。</li><li><strong>自然退出（无后台派生）</strong>：<code>exit</code> 事件 → 记录 exitCode/signal、<code>exitedAt</code>、结束日志流、唤醒等待者、<code>onChange</code>。</li><li><strong>shell 已退但作业还在（F2）</strong>：<code>isGroupAlive(rec)</code> 用 <code>process.kill(-pgid, 0)</code> 探活；此时 <code>waitForExit</code> <strong>照常返回</strong>（<code>!</code> 的前台部分已完成），但面板/摘要仍显示&quot;运行中&quot;。收尾靠 <code>refreshJobStates()</code>，它挂在<strong>渲染 / 摘要刷新路径</strong>上，<strong>不引入独立定时器</strong>。</li></ul><h2 id="_3-进程组与回收-ac-13-的核心" tabindex="-1">3. 进程组与回收（AC-13 的核心） <a class="header-anchor" href="#_3-进程组与回收-ac-13-的核心" aria-label="Permalink to &quot;3. 进程组与回收（AC-13 的核心）&quot;">​</a></h2><ul><li><code>detached: true</code> 使 <code>sh</code> 成为<strong>进程组组长</strong>（pgid === pid，已实测）。</li><li>回收一律 <code>process.kill(-pgid, signal)</code> —— <strong>连 <code>sh -c</code> 下的孙进程一起收</strong>。</li><li>顽固组（<code>trap &#39;&#39; TERM</code>）：SIGTERM 宽限（<code>taskKillGraceMs</code>，默认 2000ms）未退 → <strong>SIGKILL</strong> 再等 1000ms（探针验证过必须靠这一步）。</li><li>shell 已退的作业（F2）：没有新的 <code>exit</code> 事件可等 → <code>kill()</code> 改为 <code>waitGroupGone()</code>（25ms 轮询、有界）。</li><li><code>kill()</code> 幂等：已退出/已终止返回 <code>{killed:false, alreadyExited:true}</code> 不抛；未知 id 返回 <code>null</code>。</li><li><code>killAll()</code>：只收<strong>本次真的在运行</strong>的任务（已退出的不谎报&quot;已终止&quot;），返回清单供退出时打印（AC-15 的&quot;只剩一行 bye&quot;）。</li></ul><h2 id="_4-输出采集" tabindex="-1">4. 输出采集 <a class="header-anchor" href="#_4-输出采集" aria-label="Permalink to &quot;4. 输出采集&quot;">​</a></h2><ul><li>stdout+stderr 合流进 <code>RingBuffer</code>：<strong>2000 行 / 256KB</strong> 双阈值（<code>taskBufferMaxLines</code> / <code>taskBufferMaxBytes</code>），超出丢最旧并记 <code>droppedLines</code> / <code>droppedBytes</code>。</li><li>同步落盘 <code>~/.agent-cli/tasks/&lt;task-id&gt;.log</code>（<code>createWriteStream</code> append）；<strong>日志保留 7 天</strong>（<code>taskLogRetentionDays</code>，D18）。</li><li>落盘流的<strong>异步 open 失败</strong>（目录被并发删/磁盘故障）只以 <code>&#39;error&#39;</code> 事件出现 → 处置 = 置空 <code>rec.stream</code> 降级为仅内存缓冲（不抛、不影响任务）。</li><li><code>bash_output</code> 工具的增量读取：<code>readCursor</code> 游标 + <code>wakeActivity</code>（有输出<strong>或</strong>退出时唤醒，<code>wait_ms</code> 语义）。</li></ul><blockquote><p>行数口径与工具输出截断同源（lesson 012）：<code>countLines</code> / 字节阈值必须与 <code>tools/truncate.ts</code> 一致。</p></blockquote><h2 id="_5-bash-模式-fr-6-ac-28-35" tabindex="-1">5. <code>!</code> bash 模式（FR-6 / AC-28~35） <a class="header-anchor" href="#_5-bash-模式-fr-6-ac-28-35" aria-label="Permalink to &quot;5. `!` bash 模式（FR-6 / AC-28~35）&quot;">​</a></h2><p><code>index.ts</code> 的 <code>runBangCommand</code>：</p><ol><li><code>tasks.start(command)</code> —— <strong>前台</strong>（默认 <code>background: false</code>），立即开始采集输出。</li><li><code>await Promise.race([tasks.waitForExit(id), detachPromise])</code> —— 正常等到命令结束；<code>Ctrl+B</code> 触发 <code>detachPromise</code>。</li><li><strong>正常结束</strong>：工具行按 <code>exitCode</code> 结算 ✓/✗，输出一次性进内容区，并把 <code>[本地 shell] …</code> 作为一条 user 消息注入上下文（AC-29，落盘）。</li><li><strong>Ctrl+B 转后台（AC-32）</strong>：<code>tasks.markBackground(id)</code>（F1：此后才算&quot;后台任务&quot;进面板）→ 工具行显示 <code>↗ 已转后台</code>（<strong>不是 ✗</strong>，任务仍在跑）→ 前台等待解除。</li><li>busy 语义（V-4）：<code>!</code> 执行期间 <code>setBusy(true, {kind:&#39;bang&#39;})</code>；<strong>后台任务不计入 busy</strong> —— 否则 <code>Ctrl+C</code> 会被 ExitGuard 误判。前台回合运行中则保持 <code>kind:&#39;turn&#39;</code> 不清 busy。</li></ol><p>补全：<code>!</code> 触发的候选来自 <code>createBangHistorySource</code>（<strong>仅本会话</strong>成功执行过的命令，不读 <code>~/.zsh_history</code>，AC-34/57）。</p><h2 id="_6-llm-侧-run-in-background-bash-output-kill-task" tabindex="-1">6. LLM 侧：<code>run_in_background</code> / <code>bash_output</code> / <code>kill_task</code> <a class="header-anchor" href="#_6-llm-侧-run-in-background-bash-output-kill-task" aria-label="Permalink to &quot;6. LLM 侧：`run_in_background` / `bash_output` / `kill_task`&quot;">​</a></h2><ul><li><code>bash(run_in_background: true)</code> → <code>tasks.start(cmd, {background: true})</code>（F1：只有它和 Ctrl+B detach 的才进面板）→ 立即返回 <code>task_id</code>。</li><li><strong>非交互（单轮）模式显式拒绝后台任务</strong>（V-8）：单轮没有统一退出收尾，起后台任务 = 留孤儿进程。返回结构化错误让 LLM 改用前台。</li><li><code>bash_output(task_id)</code>：增量读输出 + <code>running</code> 状态；<code>kill_task(task_id)</code>：终止。</li></ul><h2 id="_7-任务面板-fr-3-ac-13-18" tabindex="-1">7. 任务面板（FR-3 / AC-13~18） <a class="header-anchor" href="#_7-任务面板-fr-3-ac-13-18" aria-label="Permalink to &quot;7. 任务面板（FR-3 / AC-13~18）&quot;">​</a></h2><p><code>ui/task-panel.ts</code> —— <strong>纯逻辑</strong>，通过 <code>TaskPanelSource</code> 读数：</p><ul><li><strong>面板是&quot;后台任务&quot;视图，不是 TaskManager 的镜像（F1）</strong>：<code>openTaskPanel</code> 只快照 <code>background !== false</code> 的任务。<code>!</code> 前台一次性命令、LLM 前台 bash（走 <code>execAsync</code>，根本不是任务）都不出现。</li><li><strong>快照 + 刷新</strong>：打开时快照条目集合与顺序；之后<strong>只刷新既有条目的内容</strong>（按 id 匹配）—— 条目数不变 ⇒ 高度恒定（V-5）。刷新前先 <code>refreshJobStates()</code> 收尾已死的作业。</li><li><strong><code>x</code> 直接关闭（F5）</strong>：跑着则先 <code>kill</code>，然后 <code>forget(id)</code> <strong>从管理器真移除</strong> —— 否则重开面板重新快照时它会&quot;复活&quot;。<strong>无二次确认</strong>（用户拍板，推翻原 AC-16 的二次确认设计）。</li><li><strong><code>c</code> 清理</strong>：移除所有已结束/已终止条目，同样落 <code>forgetFinished()</code>。</li><li>高度冻结 <code>TASK_PANEL_HEIGHT = 10</code>（标题 1 + 条目 8 + 提示 1）；条目多靠窗口滚动。</li><li>渲染<strong>绝不出现 <code>kind === …</code> 分支</strong>（AC-18）—— 条目带 <code>kind</code> 标签是为将来扩展（如 subagent），新增类型不改渲染代码。</li></ul><h2 id="_8-任务详情-ac-15" tabindex="-1">8. 任务详情（AC-15） <a class="header-anchor" href="#_8-任务详情-ac-15" aria-label="Permalink to &quot;8. 任务详情（AC-15）&quot;">​</a></h2><p><code>ui/fullscreen.ts</code> 的 <code>TaskDetailView</code>：</p><ul><li>构造接收 <code>TaskDetailInput</code> <strong>或读取器函数</strong>（实时模式）：每次渲染重读状态 / 命令 / <code>tailOutput(id, 1000)</code>。</li><li><strong>贴底跟随最新输出</strong>；手动上滚脱离跟随，滚回底部自动恢复。</li><li>输出以换行结尾时去掉<strong>末尾那一个</strong>空行（否则跟随态会&quot;多滚一行&quot;、底部留白）。</li><li>全屏打开期间 ticker 强制运行；<code>renderFullscreen</code> <strong>只在内容变化时重绘</strong>（<code>lastFullscreenFrame</code> 帧缓存）—— 否则 100ms tick 整屏反复清屏重写。</li></ul><h2 id="_9-坑与约束" tabindex="-1">9. 坑与约束 <a class="header-anchor" href="#_9-坑与约束" aria-label="Permalink to &quot;9. 坑与约束&quot;">​</a></h2><ol><li><strong>&quot;已结束&quot;是作业级语义（F2）</strong>：shell 退出但后代仍在 → 不是结束。反之，命令自己把输出重定向（如 <code>&amp;&gt; /dev/null</code>）时详情<strong>就是空的</strong> —— 这是命令行为，不是 bug（详情页有提示行）。</li><li><strong>面板条目数不可变</strong>（V-5）：要&quot;增删&quot;只能关掉重开面板（重开时重新快照）。</li><li><strong>不引定时器</strong>：输出采集、退出等待、作业收尾全部事件驱动 / 挂在既有渲染路径上。</li><li><strong>进程组回收必须整组</strong>：只 kill <code>sh</code> 本身会留下孙进程（lesson 018 同族）。</li><li><strong>日志流要结算</strong>：<code>kill()</code> 里 <code>settleLogStream()</code> 有界等待日志流 <code>close</code>，否则调用方（如测试的 <code>rmSync</code>）与 fd 释放赛跑 → 偶发 <code>ENOTEMPTY</code>（lesson 018）。已知残留 W-2：自然退出路径尚未同样结算。</li></ol><h2 id="_10-测试" tabindex="-1">10. 测试 <a class="header-anchor" href="#_10-测试" aria-label="Permalink to &quot;10. 测试&quot;">​</a></h2><ul><li><code>tasks.test.ts</code>：真实子进程（<code>sleep</code> / <code>trap &#39;&#39; TERM</code> / <code>&amp;</code> 派生）+ <code>ps</code> 复核无孤儿 + 日志落盘 + 作业级状态（F2）+ <code>forget</code>。</li><li><code>ui/task-panel.test.ts</code>：渲染 / 键位 / 高度恒定 / 单一形状（AC-18）+ 代码检索锁（渲染无 <code>kind</code> 分支）。</li><li><code>ui/fullscreen.test.ts</code>：渲染行数 / 跟随与滚动边界 / 实时重读 / 末尾空行。</li><li><code>ui/tui.e2e.test.ts</code>：真实子进程的 <code>x</code> 关闭、<code>Ctrl+B</code> 转后台、面板状态同步（含&quot;重开面板不复活&quot;回归）。</li></ul>',29)])])}const k=o(s,[["render",a]]);export{p as __pageData,k as default};
